      "language_code": "en",
      "language_probability": 0.98,
      "text": "Hello world",
      "words": [...]
    }
    ```

    ```python title="Multichannel response"
    {
      "transcripts": [
        {
          "language_code": "en",
          "language_probability": 0.98,
          "text": "Hello from channel one.",
          "channel_index": 0,
          "words": [...]
        },
        {
          "language_code": "en",
          "language_probability": 0.97,
          "text": "Greetings from channel two.",
          "channel_index": 1,
          "words": [...]
        }
      ]
    }
    ```

    </CodeBlocks>

  </Step>
</Steps>

