          })
        );

        // Reply to the user immediately to let them know we received their file.
        return ctx.reply('Received. Scribing...');
      } catch (error) {
        console.error(error);
        return ctx.reply(
          'Sorry, there was an error getting the file. Please try again with a smaller file!'
        );
      }
    });
    ```

  </Step>

