                if (status === "completed" || status === "failed") {
                    ids.splice(ids.indexOf(id), 1);
                }

                if (ids.length === 0) {
                    clearInterval(interval);
                    console.log("All samples have been processed or removed from polling");
                }
            }
        }, 5000);
